			function cmbOutrcMthdSelectionChange(psState) {
			    
			    var vcOutrcMthdCombo = app.lookup("cmbOutrcDscsnMthd");         // 방법
			    var vcOutrcSnsCombo = app.lookup("cmbSns");                     // SNS
			    
			    if (psState != "UPDATE") {
			//        vcOutrcSnsCombo.clearSelection();
			        vcOutrcSnsCombo.value = "";
			    }
			    
			    var vcOutrcMthdComboVal = vcOutrcMthdCombo.value;
			    
			    if (vcOutrcMthdComboVal == '1') {
			        
			        vcOutrcSnsCombo.filterExp = "value == '' || value == '01' || value == '02' || value == '03' || value == '06' || value == '07'";
			        
			    } else if (vcOutrcMthdComboVal == '6') {
			        
			        vcOutrcSnsCombo.filterExp = "value == '' || value == '04' || value == '05' || value == '99'";
			        
			    } else if (vcOutrcMthdComboVal == '7') {
			        
			        vcOutrcSnsCombo.filterExp = "value == '' || value == '04'";
			        
			    } else {
			        
			        vcOutrcSnsCombo.filterExp = "value == ''";
			        
			    }
			}
